import { generationStart } from './retained.js';
import { walletIdOf_g3120 } from './wallets.js';
import { chainClient, checkAbort, ChainDataError, logKey } from './client.js';
import { cachedEvents } from './event-store.js';
import { revealedEntries } from './tickets.js';
import { playerAddress, uint } from './state.js';
import { retainedTicketLevels } from './recycling.js';

// Whale/deity grants reach at most 100 levels ahead; boxes at most 51.
// Level L's generation window is stamped at the seal of purchase level L - 1 (audit 26ad5863),
// i.e. about when the game reaches L - 2. The window of level-104 therefore opened while the game
// was still ~six levels short of level-100, so it safely includes even far-future registry
// registrations for this level.
export async function registrationStart(s, level, signal) {
  checkAbort(signal);
  if (level <= 104) return Number(s.client.chain.deployBlock);
  const start = await generationStart(s, level - 104, signal);
  if (!start) throw new ChainDataError('Missing level registration window.', 'INCOMPLETE_HISTORY');
  return Number(start);
}
/**
 * Audit b05ea7c50: bingo and affiliate-DGNRS claim stamps share playerClaimWord[player]. Bits 0..24
 * (even ticket buffer) and 25..49 (odd) hold level + 1 of the last bingo claimed on that parity
 * (zero = never); bits 50..73 hold the level whose affiliate DGNRS was claimed. A parity stamp is
 * only overwritten once that buffer's old level has retired, so it answers exactly for every level
 * still claimable. Mirrors DegenerusGameStorage._bingoClaimed / _affiliateDgnrsClaimed.
 */
export async function bingoClaimed(s, level, player) {
  const word = BigInt(await s.field('GAME', 'playerClaimWord', player));
  return ((word >> BigInt((Number(level) & 1) * 25)) & 0x1ffffffn) === BigInt(level) + 1n;
}
export async function affiliateDgnrsClaimed(s, level, player) {
  const word = BigInt(await s.field('GAME', 'playerClaimWord', player));
  return ((word >> 50n) & 0xffffffn) === BigInt(level);
}

export async function bingoCandidates(s, rawPlayer, { level: selectedLevel, history = 'all', signal } = {}) {
  const player = playerAddress(rawPlayer);
  const current = Number(await s.field('GAME', 'level'));
  const gameOver = await s.field('GAME', 'gameOver');
  // Only level .. level + 2 can hold minted (trait-revealed) tickets: higher levels stay queued
  // unminted in the far-future key space (_mintCeiling, audit 26ad5863).
  const stamps = await retainedTicketLevels(s);
  const retained = [...new Set(stamps.filter(level => level > 0))].sort((a, b) => a - b);
  const levels = selectedLevel == null ? retained : [uint(selectedLevel)];
  // The Pending watcher only reveals rewards from the current and previous
  // level. A claim cannot predate that level's first generated ticket, so its
  // generation stamp bounds these receipts exactly. The general route keeps
  // its existing wider ledger; far-future registration is unnecessary here.
  const recentFromLevel = Math.max(0, current - 1);
  const eventsPromise = (async () => {
    const fromBlock = history === 'recent'
      ? Number(await generationStart(s, recentFromLevel, signal)) || Number(s.client.chain.deployBlock)
      : await registrationStart(s, current, signal);
    checkAbort(signal);
    const rows = await cachedEvents(s, 'GAME', 'BingoClaimed', { player }, { fromBlock, signal });
    return history === 'recent' ? rows.filter(row => Number(row.args.level) >= recentFromLevel) : rows;
  })();
  // Levels resolve concurrently: the shared log lane already bounds RPC concurrency, and walking
  // six levels of five log scans each in series outran the panel's read deadline for a whale.
  const candidatesPromise = Promise.all(levels.map(async level => {
    checkAbort(signal);
    if (gameOver || stamps[level & 1] > level) return null;
    if (await bingoClaimed(s, level, player)) return null;
    const batches = await revealedEntries(s, player, level, { signal });
    const masks = new Uint8Array(32);
    for (const batch of batches) for (const trait of batch.traits) masks[((trait >> 6) << 3) | (trait & 7)] |= 1 << ((trait >> 3) & 7);
    for (let symbol = 0; symbol < 32; symbol++) if (masks[symbol] === 255) return { player, level, quadrant: symbol >> 3, symbol, slots: null, proofPending: true };
    return null;
  }));
  const [perLevel, events] = await Promise.all([candidatesPromise, eventsPromise]);
  const claimable = perLevel.filter(Boolean);
  return { player, claimable, claimed: events.map(row => ({
    id: logKey(row), player, level: Number(row.args.level), symbol: Number(row.args.symbol), tier: 'regular',
    flipReward: String(row.args.flipReward), dgnrsPaid: String(row.args.dgnrsPaid), blockNumber: row.blockNumber,
    transactionHash: row.transactionHash, logIndex: row.logIndex,
  })), scope: { fromLevel: levels[0], toLevel: levels.at(-1) } };
}

export async function bingoProof(rawPlayer, rawLevel, rawSymbol, { signal, client = chainClient() } = {}) {
  const player = playerAddress(rawPlayer); const level = uint(rawLevel); const symbol = uint(rawSymbol, 31);
  const s = await client.snapshot({ fresh: true, signal });
  if (await s.field('GAME', 'gameOver')) throw new ChainDataError('Bingo claims have closed because the game is over.', 'GameOver');
  const stamps = await retainedTicketLevels(s);
  if (stamps[level & 1] > level) throw new ChainDataError('This Bingo claim window has closed.', 'BingoExpired');
  if (await bingoClaimed(s, level, player)) throw new ChainDataError('Bingo already claimed.', 'AlreadyClaimed');
  // Permanent wallet IDs resolve the owner directly, including tickets acquired many levels later.
  const id = await walletIdOf_g3120(s, player);
  const indices = id ? [id] : [];
  if (!indices.length) throw new ChainDataError('No registered entries for this Bingo.', 'INCOMPLETE_HISTORY');
  const slots = [];
  for (let color = 0; color < 8; color++) {
    checkAbort(signal); const trait = ((symbol >> 3) << 6) | (color << 3) | (symbol & 7); let found = null;
    for (let group = 0; group < indices.length && found == null; group += 1024) {
      let cursor = 0; let words = 512;
      while (true) {
        checkAbort(signal); let page;
        try { page = await s.call('GAME_LENS', 'findTraitEntry', [client.address('GAME'), level, trait, indices.slice(group, group + 1024), cursor, words]); }
        catch (error) {
          // Public eth_call ceilings differ. Shrink only recognizable budget
          // failures; transport failures must not turn into a missing proof.
          if (words > 1 && /gas|out of|limit|CALL_REVERTED/i.test(`${error.code} ${error.message}`)) { words = Math.max(1, words >> 1); continue; }
          throw error;
        }
        if (page.found) { found = Number(page.position); break; }
        if (page.nextOffset >= page.total) break;
        if (Number(page.nextOffset) <= cursor) throw new ChainDataError('Bingo scan made no progress.');
        cursor = Number(page.nextOffset);
      }
    }
    if (found == null) throw new ChainDataError('This Bingo no longer has all eight colors.', 'INCOMPLETE_HISTORY');
    slots.push(found);
  }
  await s.verify(signal); return slots;
}

// Reuse far-future holdings within the same level/phase, without a timed scan.
// Deity renewals are queued by the keeper at transition completion, without a
// wallet transaction. The active ticket level advances BEFORE that grant, so
// phase completion must also change the key even if the active level is equal.
const farHoldingsCache = new Map();
async function farHoldingsKey(s, player) {
  const [active, level, jackpot, transition] = await Promise.all([
    s.call('GAME_LENS', 'activeTicketLevelOf', [s.client.address('GAME')]),
    s.field('GAME', 'level'),
    s.field('GAME', 'jackpotPhaseFlag'),
    s.field('GAME', 'phaseTransitionActive'),
  ]);
  // The snapshot shares the active-level call and the phase fields' storage word.
  return `${s.client.chain.id}:${s.client.address('GAME')}:${player}:${active}:${level}:${Number(jackpot)}:${Number(transition)}`;
}
export async function cachedFarHoldings(s, player) { return farHoldingsCache.get(await farHoldingsKey(s, playerAddress(player))) ?? null; }
export async function rememberFarHoldings(s, player, rows) {
  const key = await farHoldingsKey(s, playerAddress(player)); farHoldingsCache.set(key, rows);
  for (const oldKey of farHoldingsCache.keys()) if (farHoldingsCache.size > 32 && oldKey !== key) farHoldingsCache.delete(oldKey);
}
export function clearFarHoldings() { farHoldingsCache.clear(); }
if (typeof document !== 'undefined') document.addEventListener?.('degenerus:tx-confirmed', clearFarHoldings);

// Wallets pack all 100 future levels into 13 farFutureOwed words (one 32-bit lane per circular slot
// (level - 1) % 100, bits 0..29 entries). Read each needed word once, then authenticate only
// nonempty lanes against the queue header.
// This mirrors _entriesOwedTotal, including both normal cohorts, instead of
// calling entriesOwedView separately for all 95 levels on dashboard startup.
async function walletQueuedEntries(s, ownerId, levels, signal) {
  const slots = [...new Set(levels.filter(level => level > 0).map(level => Math.floor(((level - 1) % 100) / 8)))];
  const [pending, pairs] = await Promise.all([
    s.field('GAME', 'ticketPending', ownerId),
    Promise.all(slots.map(async slot => [slot, BigInt(await s.field('GAME', 'farFutureOwed', ownerId, slot))])),
  ]);
  checkAbort(signal);
  const words = new Map(pairs);
  const lanes = levels.map(level => {
    const position = (level - 1) % 100;
    const amount = level > 0 ? (words.get(Math.floor(position / 8)) >> BigInt((position % 8) * 32)) & 0x3fffffffn : 0n;
    return { level, position, amount };
  });
  const tags = new Map(await Promise.all([...new Set(lanes.filter(row => row.amount).map(row => row.position))].map(async position => {
    const header = BigInt(await s.field('GAME', 'ticketQueue', (position + 1) | (1 << 22), 'length'));
    return [position, Number((header >> 32n) & 0xffffffn) || position + 1];
  })));
  return new Map(lanes.map(({ level, position, amount }) => {
    const parity = BigInt(level & 1);
    const tag = Number((BigInt(pending) >> (168n + parity * 24n)) & 0xffffffn);
    const shift = parity * 84n;
    const normal = tag === level
      ? ((BigInt(pending) >> (shift + 8n)) & 0xffffffffn) + ((BigInt(pending) >> (shift + 50n)) & 0xffffffffn)
      : 0n;
    return [level, Number((normal + (tags.get(position) === level ? amount : 0n)) & 0xffffffffn)];
  }));
}

export async function farFutureQueue(s, rawPlayer, { levels, signal } = {}) {
  const player = playerAddress(rawPlayer);
  const active = Number(await s.call('GAME_LENS', 'activeTicketLevelOf', [s.client.address('GAME')]));
  // Salvage distance is 2..100 from the active ticket level (MintStreakUtils, audit 26ad5863),
  // and every level that far out is above _mintCeiling(), i.e. in the far-future key space.
  const targets = levels ? levels.map(level => uint(level)) : Array.from({ length: 99 }, (_, i) => active + 2 + i);
  const rows = [];
  const ownerId = await walletIdOf_g3120(s, player);
  if (ownerId) {
    checkAbort(signal);
    const counts = await walletQueuedEntries(s, ownerId, targets, signal);
    checkAbort(signal);
    for (const level of targets) {
      const entryCount = counts.get(level);
      if (entryCount) rows.push({ level, entryCount, remainder: 0, ownerPosition: ownerId, queueIndex: null });
    }
  }
  if (!levels) await rememberFarHoldings(s, player, rows);
  return { player, rows, positionsDeferred: true, blockNumber: String(s.block.number) };
}
